"use client";

import { useEffect, useRef, useState } from "react";
import { cn } from "@/lib/utils";

/** Small card-sized derivative generated by the sync worker. */
function thumbFor(src: string): string | null {
  const match = src.match(/^\/covers\/aniplus\/([^/?]+)\.jpg(\?.*)?$/);
  if (!match) return null;
  return `/covers/aniplus/${match[1]}-thumb.webp${match[2] ?? ""}`;
}

/**
 * Real cover/banner artwork with a tiny inline blur placeholder.
 * Falls back to the original image if the lightweight card derivative is
 * missing, and to a solid tint if the original never loads.
 */
export function CoverImage({
  src,
  blur,
  alt = "",
  sizes = "(max-width: 640px) 45vw, 240px",
  priority = false,
  thumb = false,
  position = "50% 50%",
  zoom = true,
  fit = "cover",
  className,
}: {
  src: string;
  blur?: string;
  alt?: string;
  sizes?: string;
  priority?: boolean;
  thumb?: boolean;
  position?: string;
  zoom?: boolean;
  fit?: "cover" | "contain";
  className?: string;
}) {
  const ref = useRef<HTMLImageElement>(null);
  const [loaded, setLoaded] = useState(false);
  const [thumbFailed, setThumbFailed] = useState(false);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    setThumbFailed(false);
    setFailed(false);
  }, [src]);

  const derivative = thumb && !thumbFailed ? thumbFor(src) : null;
  const imageSrc = failed ? "/covers/placeholder.svg" : (derivative ?? src);

  // Images that finish before hydration never fire `onLoad`, so check once mounted.
  useEffect(() => {
    if (ref.current?.complete) setLoaded(true);
  }, [imageSrc]);

  return (
    <>
      {blur && !thumb ? (
        <span
          aria-hidden
          className={cn(
            "absolute inset-0 bg-cover blur-xl transition-opacity duration-500",
            zoom && "scale-105",
            loaded ? "opacity-0" : "opacity-100",
          )}
          style={{ backgroundImage: `url("${blur}")`, backgroundPosition: position }}
        />
      ) : null}
      <img
        key={imageSrc}
        ref={ref}
        src={imageSrc}
        alt={alt}
        sizes={sizes}
        loading={priority ? "eager" : "lazy"}
        decoding="async"
        fetchPriority={priority ? "high" : "auto"}
        onLoad={() => setLoaded(true)}
        onError={() => {
          if (derivative) {
            setLoaded(false);
            setThumbFailed(true);
          } else if (!failed) {
            setLoaded(true);
            setFailed(true);
          } else {
            setLoaded(true);
          }
        }}
        className={cn(
          "absolute inset-0 size-full object-cover transition-[opacity,transform] duration-500 ease-snap",
          thumb ? "" : "brightness-[1.08] saturate-[1.03]",
          loaded ? "opacity-100" : "opacity-0",
          zoom ? (loaded ? "scale-100" : "scale-[1.04]") : "",
          className,
        )}
        style={{ objectPosition: position, objectFit: fit }}
      />
    </>
  );
}
